insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'selas'), 'Sela de Vaqueiro', 'Sela artesanal estilo vaqueiro, em couro curtido de alta resistência. Trabalhada à mão para encaixe perfeito e durabilidade excepcional.', ARRAY['Couro curtido de alta resistência', 'Acabamento manual caprichado', 'Ajuste personalizado disponível']::text[], 'Mais pedido', '', 'assets/images/sela.webp', 1);
