insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'consertos'), 'Conserto de Selas e Arreios', 'Sua sela ou arreio com costura solta, couro ressecado ou ferragem quebrada? A Márcia resolve com o mesmo capricho de uma peça nova.', ARRAY['Costura e reforço de peças', 'Troca de fivelas e ferragens', 'Avaliação sem compromisso']::text[], null, '', 'assets/images/conserto.webp', 1);
insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'consertos'), 'Restauração de Peças Antigas', 'Tem aquela peça com história que merecia uma segunda vida? Restauração de peças antigas em couro, com respeito pela originalidade.', ARRAY['Restauração cuidadosa', 'Hidratação e limpeza profunda', 'Peças com valor sentimental']::text[], 'Especial', 'gold', 'assets/images/conserto.webp', 2);
