insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'sobmedida'), 'Cinto para Coluna', 'Cinto ortopédico em couro legítimo para suporte lombar. Acabamento artesanal com costura reforçada, interior acolchoado e fivela metálica — feito sob medida para o seu conforto.', ARRAY['Couro legítimo com costura reforçada', 'Interior acolchoado para conforto', 'Medidas personalizadas']::text[], 'Sob medida', 'gold', 'assets/images/cinto-coluna.webp', 1);
insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'sobmedida'), 'Peça Personalizada', 'Tem uma ideia na cabeça? A Márcia faz. Descreva o que você quer — o couro, o tamanho, os detalhes — e receba uma peça única.', ARRAY['Projeto junto com o cliente', 'Gravação e bordado personalizado', 'Presente com significado']::text[], 'Especial', 'gold', 'assets/images/personalizado.webp', 2);
insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'sobmedida'), 'Presente Personalizado', 'Um presente em couro com o nome da pessoa, uma data especial ou um brasão de família. Algo que vai durar e ser lembrado.', ARRAY['Gravação de nomes e datas', 'Embalagem especial disponível', 'Prazo combinado com antecedência']::text[], 'Presente', '', 'assets/images/personalizado.webp', 3);
insert into public.produtos (categoria_id, nome, descricao, detalhes, badge, badge_mod, imagem, ordem) values ((select id from public.categorias where slug = 'sobmedida'), 'Encomenda Especial', 'Peças fora do padrão — tamanhos especiais, combinações incomuns, projetos únicos. Se é de couro, a Márcia sente, analisa e faz.', ARRAY['Sem limitação de modelo', 'Consulta gratuita por WhatsApp', 'Orçamento sem compromisso']::text[], null, '', 'assets/images/personalizado.webp', 4);
